// Dynamic Expo config. Identity comes from factory-app.json (final app name = displayName), version from package.json.
// android/ is generated by `npx expo prebuild` and git-ignored: native changes go through config plugins only.
const fs = require('fs');
const path = require('path');

const meta = require('./factory-app.json');
const { version } = require('./package.json');

const GOOGLE_SERVICES = './firebase/google-services.json';
const hasFirebase = fs.existsSync(path.join(__dirname, GOOGLE_SERVICES));

function versionCode(v) {
  const [major, minor, patch] = v.split('.').map((n) => parseInt(n, 10) || 0);
  return major * 10000 + minor * 100 + patch;
}

// Firebase plugins are added only when the local google-services.json exists (`expo install` may have put them in app.json).
const FIREBASE_PLUGINS = ['@react-native-firebase/app', '@react-native-firebase/analytics', '@react-native-firebase/crashlytics'];
const pluginName = (p) => (Array.isArray(p) ? p[0] : p);

// Launcher name per language: displayName for the reference language (languages[0]), displayNames.<lang> for the
// others. Each language gets its own Android resource; the default one carries the fallback language's name, so a
// phone in an unsupported language shows the same language under the icon as in the game.
const languages = meta.languages || [];
const names = { ...(meta.displayNames || {}), ...(languages.length ? { [languages[0]]: meta.displayName } : {}) };
const multilingual = languages.length > 1;
const defaultName = multilingual ? names[meta.fallbackLanguage] || meta.displayName : meta.displayName;
const locales = multilingual
  ? Object.fromEntries(languages.map((lang) => [lang, { android: { app_name: names[lang] || meta.displayName } }]))
  : undefined;

module.exports = ({ config }) => ({
  ...config,
  name: defaultName,
  ...(locales ? { locales: { ...config.locales, ...locales } } : {}),
  slug: meta.slug,
  version,
  orientation: config.orientation || 'portrait',
  android: {
    ...config.android,
    package: meta.package,
    versionCode: versionCode(version),
    // Privacy: no advertising ID.
    blockedPermissions: [
      'com.google.android.gms.permission.AD_ID',
      // Privacy Sandbox ad measurement and install referrer pulled in by Firebase Analytics: not used.
      'android.permission.ACCESS_ADSERVICES_AD_ID',
      'android.permission.ACCESS_ADSERVICES_ATTRIBUTION',
      'android.permission.ACCESS_ADSERVICES_TOPICS',
      'com.google.android.finsky.permission.BIND_GET_INSTALL_REFERRER_SERVICE',
      // Expo template defaults that a small offline game does not need.
      'android.permission.SYSTEM_ALERT_WINDOW',
      'android.permission.READ_EXTERNAL_STORAGE',
      'android.permission.WRITE_EXTERNAL_STORAGE',
    ],
    ...(hasFirebase ? { googleServicesFile: GOOGLE_SERVICES } : {}),
  },
  plugins: [
    ...(config.plugins || []).filter((p) => !FIREBASE_PLUGINS.includes(pluginName(p))),
    ...(hasFirebase ? FIREBASE_PLUGINS : []),
    './plugins/with-release-signing',
  ],
  extra: { ...config.extra, firebaseEnabled: hasFirebase },
});
